PRAGMA auto_vacuum=OFF; PRAGMA page_size=512; CREATE TABLE abc(a PRIMARY KEY,b,c); WITH RECURSIVE n(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<512) INSERT INTO abc(a,b,c) SELECT CAST(zeroblob((CASE WHEN x=2 THEN 1000 WHEN x BETWEEN 65 AND 128 OR x BETWEEN 257 AND 512 THEN 25 ELSE 100 END)-4)||CAST(printf('%04d',x) AS BLOB) AS BLOB),zeroblob(CASE WHEN x BETWEEN 65 AND 128 OR x BETWEEN 257 AND 512 THEN 45 ELSE 200 END),zeroblob(CASE WHEN x=2 THEN 100 WHEN x BETWEEN 65 AND 128 OR x BETWEEN 257 AND 512 THEN 9456 ELSE 1000 END) FROM n;